    L_mine = [&]() -> V { V out_ = V::list(); V L_x; { V it3_ = py::iter_list(rd(pvz::getattr(L_room, SY("decks")), a_side)); for (size_t i3_ = 0; i3_ < it3_.len(); ++i3_) { L_x = it3_.idx(int64_t(i3_)); out_.append(pm_rv_draftk::f_name(Args{L_x})); }}return out_; }();
