    { V ut5_ = py::as_seq(rd(L_scored, V(0.0))); L_sc = ut5_.idx(0); L_k = ut5_.idx(1); L_reasons = ut5_.idx(2); } 
    (void)(py::m_append(a_log, V::tuple({rd(L_act, SV("stage")), SV("禁"), pm_rv_draftk::f_name(Args{L_k}), py::round(L_sc), L_reasons})));
    return L_k;
